const ADV = (id, areaId, lessonId, topic, prompt, choices, answer, why, hints, calculation) => ({ id, areaId, lessonId, topic, prompt, choices, answer, why, hints, difficulty: 'Difícil', level: 'padrao-enade', origin: 'autoral', year: 2026, source: 'Questão autoral de treinamento. Competências da Portaria Inep 164/2026; não reproduz item do INEP.', status: 'resolucao-independente-revisada', revisionDate: '2026-11-05', calculation });
export const ADVANCED_QUESTIONS = [
    ADV('ADV-001', 'EE11', 'potencia-trifasica', 'Compensação de reativos', 'Uma indústria demanda 200 kW de potência ativa, com cargas indutivas e fator de potência de 0,72. Pretende-se elevar o fator de potência global para 0,95 por compensação capacitiva ideal, mantendo a potência ativa e sem considerar harmônicos. Qual potência reativa nominal aproximada deve ser compensada?', ['52 kvar', '87 kvar', '127 kvar', '181 kvar', '278 kvar'], 2, '1) Q inicial = P·tan(arccos 0,72) ≈ 192,8 kvar. 2) Q final = P·tan(arccos 0,95) ≈ 65,7 kvar. 3) Compensação Qc = Qi−Qf ≈ 127,0 kvar. O banco exige dimensionamento por degraus e estudo de harmônicos/ressonância na prática; fator de potência elevado não elimina toda corrente reativa.', ['A potência ativa permanece em 200 kW.', 'Compare a potência reativa antes e depois da compensação.', 'Use Qc=P[tan(arccos fpi)−tan(arccos fpf)].'], '200*(tan(acos(.72))-tan(acos(.95)))≈127.03 kvar'),
    ADV('ADV-002', 'EE11', 'potencia-trifasica', 'Corrente, fator de potência e cabos', 'Um alimentador trifásico equilibrado fornece 100 kW a uma carga senoidal com tensão de linha de 480 V e fator de potência 0,82. Desprezando perdas do alimentador, qual corrente de linha deve ser considerada inicialmente na avaliação térmica dos condutores?', ['104,2 A', '120,2 A', '146,7 A', '175,8 A', '254,0 A'], 2, '1) Em carga trifásica equilibrada, P=√3·Vlinha·Ilinha·FP. 2) I=P/(√3·V·FP). 3) I=100000/(√3·480·0,82)=146,7 A. É apenas uma etapa do dimensionamento; capacidade de condução, método de instalação, queda de tensão e curto-circuito também importam.', ['Observe que são 100 kW ativos, não 100 kVA.', 'Utilize grandezas de linha.', 'Não esqueça o fator de potência no denominador.'], '100000/(sqrt(3)*480*.82)=146.68 A'),
    ADV('ADV-003', 'EE11', 'curto-circuito-pu', 'Curto-circuito em base por unidade', 'Um transformador trifásico de 10 MVA e 13,8 kV no lado analisado apresenta reatância de curto-circuito de 0,20 pu na própria base. Considere fonte de potência de curto-circuito infinita, tensão pré-falta de 1 pu e despreze resistência. Qual é a corrente inicial simétrica aproximada de uma falta trifásica nos terminais?', ['0,42 kA', '1,05 kA', '2,09 kA', '5,23 kA', '10,46 kA'], 2, '1) Corrente-base: Ib=Sbase/(√3·Vbase)=10 MVA/(√3·13,8 kV)=418,4 A. 2) Para V=1 pu e X=0,20 pu, Ifpu=1/0,20=5 pu. 3) If=5·418,4 A≈2,09 kA. Este é modelo simplificado; rede a montante e impedâncias adicionais alteram o resultado.', ['Converta primeiro 10 MVA e 13,8 kV para corrente-base.', 'A corrente de falta em pu é Vpu/Zpu.', 'Multiplique o resultado em pu pela corrente-base.'], '(10e6/(sqrt(3)*13800))/.2≈2091.85 A'),
    ADV('ADV-004', 'EE12', 'solar-estimativa', 'Perdas técnicas em alimentador', 'Durante uma medição, cada fase de um alimentador trifásico equilibrado conduz 50 A eficazes. A resistência total equivalente de cada condutor de fase, na temperatura de operação, é 0,28 Ω. Desconsiderando neutro e efeitos adicionais, qual é a perda ativa total por efeito Joule nas três fases?', ['0,70 kW', '1,40 kW', '2,10 kW', '3,50 kW', '7,00 kW'], 2, 'Cada fase dissipa I²R=50²·0,28=700 W. Como são três fases equivalentes, Pperdas=3·700=2100 W=2,10 kW. Usar apenas I²R daria a perda por fase, não o total.', ['Calcule I²R de um condutor.', 'Há três condutores de fase com a mesma corrente.'], '3*50^2*.28=2100 W'),
    ADV('ADV-005', 'EE15', 'maquina-inducao', 'Escorregamento de motor de indução', 'Um motor de indução trifásico de quatro polos é alimentado a 60 Hz. Sob carga, a rotação medida é 1746 rpm. Qual o escorregamento percentual aproximado?', ['1,5%', '2,0%', '3,0%', '4,0%', '6,0%'], 2, '1) A rotação síncrona de um motor de 4 polos em 60 Hz é ns=120·f/p=1800 rpm. 2) O escorregamento é s=(ns−n)/ns=(1800−1746)/1800=0,03=3%. Em motores de indução, a rotação do rotor é menor que a síncrona em regime motor.', ['Calcule a rotação síncrona com 120f/p.', 'Subtraia a velocidade do rotor da velocidade síncrona.'], '(1800-1746)/1800*100=3%'),
    ADV('ADV-006', 'EE15', 'maquina-inducao', 'Torque útil no eixo', 'Um motor entrega 15 kW de potência mecânica útil no eixo a 1746 rpm. Admitindo regime permanente, qual o torque útil aproximado em N·m?', ['41 N·m', '65 N·m', '82 N·m', '105 N·m', '164 N·m'], 2, 'A potência mecânica no eixo é P=T·ω e ω=2πn/60. Então T=15000/[2π·1746/60]≈82,0 N·m. O cálculo usa potência mecânica útil; se fosse potência elétrica de entrada, seria necessário considerar o rendimento.', ['Converta rpm em rad/s.', 'A potência fornecida já é mecânica útil.'], '15000/(2*pi*1746/60)≈82.05 Nm'),
    ADV('ADV-007', 'EE06', 'transitorios-rlc', 'Resposta transitória RL', 'Uma bobina ideal de 0,4 H e resistência série de 8 Ω é conectada a uma fonte contínua ideal em t=0. A corrente inicial é zero. Em t=0,10 s, qual fração aproximada da corrente final terá sido atingida?', ['36,8%', '50,0%', '63,2%', '86,5%', '98,2%'], 3, '1) A constante de tempo do circuito é τ=L/R=0,4/8=0,05 s. 2) A resposta à energização é i(t)/i∞=1−exp(−t/τ). 3) Em 0,10 s, t/τ=2, logo 1−e^(−2)=0,8647≈86,5%. A exponencial não representa crescimento linear.', ['Calcule τ=L/R.', 'Divida o instante por τ.', 'Use 1−exp(−t/τ).'], '100*(1-exp(-.1/(.4/8)))=86.466%'),
    ADV('ADV-008', 'EE06', 'transitorios-rlc', 'Constante de tempo RC', 'Um capacitor inicialmente descarregado é carregado por uma fonte ideal através de R=10 kΩ e C=100 µF. A partir de qual instante a tensão alcança aproximadamente metade do valor final, no modelo RC ideal?', ['0,069 s', '0,347 s', '0,693 s', '1,000 s', '1,443 s'], 2, 'τ=RC=10000·100·10⁻⁶=1 s. Como v/Vfinal=1−exp(−t/τ), a condição v/Vfinal=0,5 implica exp(−t/τ)=0,5 e t=τ·ln 2≈0,693 s. A metade ocorre antes de uma constante de tempo, quando a tensão estaria em 63,2%.', ['Determine a constante de tempo RC.', 'Resolva exp(−t/τ)=0,5.'], '1*ln(2)=.693147 s'),
    ADV('ADV-009', 'EE06', 'transitorios-rlc', 'Ressonância RLC série', 'Um circuito RLC série apresenta L=20 mH e C=100 µF. No modelo ideal, qual a frequência de ressonância aproximadamente?', ['35,6 Hz', '79,6 Hz', '112,5 Hz', '159,2 Hz', '355,9 Hz'], 2, 'Na ressonância série, as reatâncias indutiva e capacitiva se cancelam: ω0=1/√(LC). Portanto f0=1/(2π√(0,020·100·10⁻⁶))≈112,5 Hz. A resistência afeta o amortecimento e a largura de banda, não a expressão ideal indicada.', ['Converta mH e µF para unidades SI.', 'Use f0=1/(2π√LC).'], '1/(2*pi*sqrt(.02*100e-6))≈112.54 Hz'),
    ADV('ADV-010', 'EE18', 'controle-malha', 'Realimentação não unitária', 'Um sistema de controle com realimentação negativa tem ganho direto estático G=5 e sensor com ganho H=0,2. Para uma entrada constante de amplitude 10, considere linearidade e regime permanente. Qual valor de saída é previsto pelo modelo em malha fechada?', ['5', '10', '20', '25', '50'], 3, 'O ganho de referência para saída é T=G/(1+GH)=5/(1+1)=2,5. Para a entrada de amplitude 10, y=2,5·10=25. Atenção: a realimentação não é unitária; usar G/(1+G) seria incorreto.', ['Primeiro calcule GH.', 'Use T=G/(1+GH) e multiplique pela referência.'], '(5/(1+5*.2))*10=25'),
    ADV('ADV-011', 'EE10', 'votacao-protecao', 'Confiabilidade de votação 2 de 3', 'Uma lógica de proteção utiliza votação 2 de 3 entre sensores independentes. Cada sensor tem probabilidade 0,90 de detectar corretamente uma condição de disparo. A lógica atua quando pelo menos dois sensores detectam. Qual a probabilidade de atuação correta, desconsiderando falhas de lógica e de canais comuns?', ['72,9%', '81,0%', '90,0%', '97,2%', '99,9%'], 3, 'Há duas situações favoráveis: exatamente dois sensores corretos, com probabilidade C(3,2)·p²·(1−p)=3·0,9²·0,1=0,243; e três corretos, com p³=0,729. Total=0,972=97,2%. Independência é hipótese crucial; falhas comuns comprometem a vantagem da redundância.', ['Use distribuição binomial.', 'Some P(exatamente 2) com P(exatamente 3).'], '3*.9^2*.1+.9^3=.972'),
    ADV('ADV-012', 'EE19', 'bayes-confiabilidade', 'Redundância e falhas independentes', 'Duas unidades redundantes e independentes devem manter uma função enquanto pelo menos uma funciona. Cada unidade tem probabilidade 0,02 de falhar no intervalo analisado. Qual a probabilidade de perda total da função nesse intervalo?', ['0,0004 (0,04%)', '0,0200 (2%)', '0,0396 (3,96%)', '0,0400 (4%)', '0,9604 (96,04%)'], 0, 'A função somente é perdida se as duas unidades falharem: P(F1∩F2)=P(F1)P(F2)=0,02²=0,0004, correspondente a 0,04%. O resultado não vale na presença de falha de causa comum.', ['Identifique o evento que causa perda total.', 'Como as falhas são independentes, multiplique.'], '0.02^2=.0004'),
    ADV('ADV-013', 'EE05', 'nyquist', 'Aliasing em aquisição de vibração', 'Um sinal senoidal de frequência 850 Hz é amostrado uniformemente a 1200 amostras/s, sem filtro anti-aliasing. Considerando a banda de 0 a fs/2, qual frequência aparente será observada após a amostragem?', ['150 Hz', '250 Hz', '350 Hz', '600 Hz', '850 Hz'], 2, 'A frequência de Nyquist é fs/2=600 Hz. Como 850 Hz excede esse valor, a componente se reflete: f_alias=|850−1200|=350 Hz. O sistema medirá uma componente indistinguível de 350 Hz; sem filtro anti-aliasing, o problema não é resolvido aumentando apenas a resolução em bits.', ['Qual é a frequência de Nyquist?', 'Reflita a frequência acima de fs/2 para a banda observável.'], 'abs(850-1200)=350 Hz'),
    ADV('ADV-014', 'EE14', 'adc-calibracao', 'ADC e resolução de medição', 'Um conversor analógico-digital ideal de 12 bits recebe tensão na faixa unipolar de 0 a 10 V. Qual a resolução aproximada de um passo de quantização, usando 2¹² níveis?', ['0,24 mV', '1,22 mV', '2,44 mV', '4,88 mV', '24,4 mV'], 2, 'Um ADC ideal de 12 bits possui 2¹²=4096 códigos. O tamanho aproximado do LSB é 10 V/4096≈0,002441 V=2,44 mV. Resolução não é sinônimo de exatidão, pois ruído, erro de offset e não linearidade podem dominar a medição real.', ['Quantos níveis existem em 12 bits?', 'Divida a amplitude de 10 V pelo número de níveis.'], '10000/4096≈2.441 mV'),
    ADV('ADV-015', 'EE11', 'potencia-trifasica', 'Ligação em triângulo', 'Uma carga trifásica equilibrada resistiva é ligada em triângulo à rede de 400 V entre linhas. Cada ramo possui resistência de 20 Ω e todas as tensões são senoidais. Qual é a potência ativa total?', ['4 kW', '8 kW', '12 kW', '24 kW', '48 kW'], 3, 'Em triângulo, cada resistor recebe a tensão de linha de 400 V. A potência por ramo é Pφ=V²/R=400²/20=8000 W. Três ramos dissipam 3·8000=24000 W=24 kW. Tratar a tensão como Vlinha/√3 confunde triângulo com estrela.', ['Qual tensão recebe cada ramo em triângulo?', 'Calcule P=V²/R para um ramo e multiplique por três.'], '3*400^2/20=24000 W'),
    ADV('ADV-016', 'EE11', 'potencia-trifasica', 'Ligação em estrela', 'Uma carga trifásica equilibrada resistiva é ligada em estrela a uma fonte de 400 V entre linhas. Cada fase tem 20 Ω. Qual é a potência total aproximada?', ['4 kW', '8 kW', '12 kW', '24 kW', '48 kW'], 1, 'Em estrela equilibrada, a tensão de fase é Vφ=400/√3≈230,94 V. Cada fase dissipa Vφ²/R≈2666,7 W. Somando as três fases, Ptotal=3·Vφ²/R=400²/20=8000 W=8 kW. A comparação com a ligação em triângulo mostra a importância da tensão de fase.', ['Em estrela, a tensão de fase não é igual à tensão de linha.', 'Use Vφ=Vlinha/√3 e calcule três fases.'], '3*(400/sqrt(3))^2/20=8000 W'),
    ADV('ADV-017', 'EE15', 'maquina-inducao', 'Rendimento de transformador real', 'Durante ensaio de um transformador, a carga recebe 250 kW de potência ativa. As perdas no ferro e no cobre, nas condições avaliadas, são 5 kW e 8 kW, respectivamente. Qual rendimento aproximado?', ['91,0%', '93,0%', '95,1%', '97,0%', '98,0%'], 2, 'A potência de entrada é a potência entregue mais perdas: Pin=250+5+8=263 kW. O rendimento é η=Pout/Pin=250/263≈0,95057=95,1%. Não dividir pelas perdas nem usar kVA sem conhecer o fator de potência.', ['Some as perdas à potência de saída.', 'η=Psaida/(Psaida+perdas).'], '250/(250+5+8)*100≈95.057%'),
    ADV('ADV-018', 'EE01', 'economia-projeto', 'Análise de retorno simples', 'Uma melhoria energética exige investimento inicial de R$ 100.000. Ela gera economia bruta de R$ 20.000 por ano, mas exige R$ 8.000 anuais de manutenção adicional. Desprezando inflação, tributos e valor temporal do dinheiro, qual o tempo de retorno simples?', ['5,0 anos', '6,3 anos', '8,3 anos', '10,0 anos', '12,5 anos'], 2, 'O benefício líquido anual é R$ 20.000−R$ 8.000=R$ 12.000. Payback simples=investimento/benefício líquido=100000/12000≈8,33 anos. O retorno simples não é VPL e não considera custo de capital; deve ser evitado como único critério de investimento.', ['Calcule a economia líquida anual.', 'Divida o investimento inicial pela economia líquida.'], '100000/(20000-8000)=8.333 years'),
    ADV('ADV-019', 'EE12', 'solar-estimativa', 'Estimativa de geração fotovoltaica', 'Um sistema fotovoltaico tem potência instalada de 5 kWp, irradiação diária média equivalente a 5,2 horas de sol pleno e taxa de desempenho global (PR) estimada em 0,78. Qual a energia elétrica diária aproximada, sob essas hipóteses?', ['15,6 kWh', '18,2 kWh', '20,3 kWh', '25,0 kWh', '33,3 kWh'], 2, 'A aproximação usual é E=Ppico·HSP·PR. Portanto E=5 kWp·5,2 h·0,78=20,28 kWh por dia. A estimativa não substitui análise de sombreamento, orientação, temperatura, degradação e sazonalidade.', ['Horas de sol pleno representam energia solar diária equivalente.', 'Multiplique potência de pico, HSP e PR.'], '5*5.2*.78=20.28 kWh/day'),
    ADV('ADV-020', 'EE08', 'magnetismo', 'Lei de Faraday', 'Uma bobina de 250 espiras sofre variação aproximadamente uniforme do fluxo magnético por espira, de 5 mWb para 1 mWb, em 0,04 s. Qual é o módulo da força eletromotriz média induzida?', ['2,5 V', '10 V', '20 V', '25 V', '100 V'], 3, 'Pela lei de Faraday, |e|=N·|ΔΦ|/Δt. A variação por espira é |1−5| mWb=0,004 Wb. Então |e|=250·0,004/0,04=25 V. O sinal da tensão depende da convenção de polaridade e corresponde à oposição da lei de Lenz.', ['Converta mWb em Wb.', 'Multiplique a variação de fluxo pelo número de espiras.'], '250*.004/.04=25 V'),
    ADV('ADV-021', 'EE15', 'maquina-inducao', 'Potência no rotor de motor de indução', 'Em regime motor, um motor de indução apresenta potência transferida pelo entreferro de 50 kW e escorregamento de 4%. No modelo clássico, qual potência é dissipada por efeito Joule no circuito equivalente do rotor?', ['0,5 kW', '1,0 kW', '2,0 kW', '4,0 kW', '48,0 kW'], 2, 'A potência dissipada no rotor é Pcu,rotor=s·Pag=0,04·50 kW=2,0 kW. A potência mecânica eletromagnética convertida é (1−s)·Pag=48 kW, antes de perdas mecânicas adicionais.', ['O escorregamento é uma fração: 4%=0,04.', 'Use Pcu,rotor=s·Potência do entreferro.'], '0.04*50=2 kW'),
    ADV('ADV-022', 'EE13', 'tcs-protecao', 'Transformador de corrente em proteção', 'Um transformador de corrente ideal apresenta relação 600/5 A. Durante uma falta, a corrente primária simétrica é de 3600 A. Qual corrente secundária ideal corresponde a esse valor, desprezando saturação e carga secundária?', ['5 A', '15 A', '20 A', '30 A', '60 A'], 3, 'A relação nominal é 600/5=120:1. Assim, Isec=3600/120=30 A. O resultado é ideal; em faltas elevadas, saturação do núcleo, remanência e burden precisam ser avaliados antes de inferir o sinal real visto pelo relé.', ['Calcule a relação primário/secundário.', 'Divida 3600 A pela relação 120.'], '3600/(600/5)=30 A'),
    ADV('ADV-023', 'EE06', 'transitorios-rlc', 'Descarga exponencial de capacitor', 'Um capacitor ideal de 470 µF é inicialmente carregado a 100 V e depois descarrega exclusivamente por um resistor de 2 kΩ. Em que instante, aproximadamente, a tensão atinge 25 V?', ['0,33 s', '0,65 s', '0,94 s', '1,30 s', '2,60 s'], 3, 'A constante de tempo é τ=RC=2000·470·10⁻⁶=0,94 s. Na descarga, v(t)=V0 exp(−t/τ), então t=τ·ln(V0/V)=0,94·ln 4≈1,303 s. Não confunda atingir 25% com passar um quarto do tempo de descarga.', ['Encontre τ=RC.', 'Resolva exp(−t/τ)=0,25.'], '2000*470e-6*ln(4)=1.303 s'),
    ADV('ADV-024', 'EE19', 'bayes-confiabilidade', 'Probabilidade condicional e falso positivo', 'Uma falha rara ocorre em 1% dos equipamentos. Um teste identifica corretamente 95% dos equipamentos com falha (sensibilidade), mas indica positivo em 5% dos equipamentos sem falha. Para um resultado positivo, qual a probabilidade aproximada de que o equipamento realmente esteja com falha?', ['1,0%', '5,0%', '16,1%', '50,0%', '95,0%'], 2, 'P(falha|positivo)=P(positivo|falha)·P(falha)/P(positivo). O numerador é 0,95·0,01=0,0095. O denominador soma positivos verdadeiros e falsos: 0,0095+0,05·0,99=0,059. Resultado 0,0095/0,059≈0,161=16,1%. Um teste sensível não implica alta probabilidade posterior quando o evento é raro.', ['Faça uma árvore de probabilidade para falha e não falha.', 'Calcule os positivos verdadeiros e falsos.', 'Use o teorema de Bayes.'], '(.95*.01)/(.95*.01+.05*.99)=.1610'),
    ADV('ADV-025', 'EE18', 'estabilidade-polos', 'Estabilidade de segunda ordem', 'A função de transferência de malha fechada de um sistema linear e invariante no tempo tem denominador s²+4s+13. Considerando o modelo contínuo, o que se pode afirmar sobre a estabilidade e a natureza dos polos?', ['Instável com dois polos reais positivos.', 'Estável com polos −2±j3.', 'Estável com polos +2±j3.', 'Marginalmente estável com polos imaginários puros.', 'Instável por conter dois polos complexos.'], 1, 'Resolver s²+4s+13=0 dá s=[−4±√(16−52)]/2=−2±j3. Os polos possuem parte real negativa; assim, o sistema contínuo é assintoticamente estável no modelo linear. A parte imaginária provoca oscilação amortecida.', ['Use a fórmula de Bhaskara.', 'A estabilidade depende do sinal da parte real dos polos.'], 'roots of s²+4s+13 => -2±3j'),
    ADV('ADV-026', 'EE11', 'potencia-trifasica', 'Fator de potência e corrente de entrada', 'Uma carga trifásica equilibrada consome 90 kW sob tensão de linha constante de 400 V. Após compensação de reativos, seu fator de potência muda de 0,75 para 0,90 sem alteração da potência ativa. Qual a redução relativa aproximada da corrente de linha?', ['8,3%', '12,5%', '16,7%', '20,0%', '25,0%'], 2, 'Com P e V constantes, a corrente é inversamente proporcional ao fator de potência: If/Ii=FPi/FPf=0,75/0,90=0,8333. A redução relativa é (1−0,8333)·100≈16,7%. Não é necessário conhecer a corrente absoluta para comparar os dois regimes.', ['As duas operações têm mesma P e V.', 'A corrente é proporcional a 1/FP.'], '(1-0.75/0.9)*100=16.67%')
];
